WITH base AS (SELECT *, DATE_TRUNC('YEAR', txn_time) AS txn_time_period FROM transactions WHERE is_flagged OR txn_time < '2024-05-01'), txn_month_summary AS (SELECT MONTH(txn_time) AS txn_month, CASE WHEN amount >= 4400 THEN 'high' WHEN amount >= 1400 THEN 'mid' ELSE 'low' END AS amount_bucket, MAX(amount) AS max_amount, ROUND(AVG(amount), 2) AS avg_amount FROM base GROUP BY MONTH(txn_time), CASE WHEN amount >= 4400 THEN 'high' WHEN amount >= 1400 THEN 'mid' ELSE 'low' END) SELECT txn_month, amount_bucket, max_amount, avg_amount FROM txn_month_summary ORDER BY avg_amount DESC, txn_month, amount_bucket LIMIT 5
